# Added apply function

def apply(func, *args, **kwargs):
    """Invoke a callable with given arguments.

    Equivalent to ``func(*args, **kwargs)``.
    """
    return func(*args, **kwargs)

# Added compose_left function

def compose_left(*funcs):
    """Compose functions left-to-right.

    Returns a function that applies *funcs* from left to right.
    Equivalent to ``pipe`` but returns a function.
    """
    if not funcs:
        return identity
    def composed(*args, **kwargs):
        result = funcs[0](*args, **kwargs)
        for f in funcs[1:]:
            result = f(result)
        return result
    return composed
